// ─── Tests ────────────────────────────────────────────────────────────────────
// Do not edit this file.

package mergesort

import (
	"reflect"
	"testing"
)

func eq(a, b []int) bool {
	if len(a) == 0 && len(b) == 0 {
		return true
	}
	return reflect.DeepEqual(a, b)
}

func TestEmpty(t *testing.T) {
	if got := MergeSort([]int{}); !eq(got, []int{}) {
		t.Fatalf("got %v, want []", got)
	}
}

func TestSingle(t *testing.T) {
	if got := MergeSort([]int{7}); !eq(got, []int{7}) {
		t.Fatalf("got %v, want [7]", got)
	}
}

func TestSorted(t *testing.T) {
	if got := MergeSort([]int{1, 2, 3, 4, 5}); !eq(got, []int{1, 2, 3, 4, 5}) {
		t.Fatalf("got %v", got)
	}
}

func TestReverse(t *testing.T) {
	if got := MergeSort([]int{5, 4, 3, 2, 1}); !eq(got, []int{1, 2, 3, 4, 5}) {
		t.Fatalf("got %v", got)
	}
}

func TestMixed(t *testing.T) {
	if got := MergeSort([]int{5, 2, 4, 1, 3}); !eq(got, []int{1, 2, 3, 4, 5}) {
		t.Fatalf("got %v", got)
	}
}

func TestDuplicates(t *testing.T) {
	if got := MergeSort([]int{3, 1, 2, 3, 1}); !eq(got, []int{1, 1, 2, 3, 3}) {
		t.Fatalf("got %v", got)
	}
}

func TestNegatives(t *testing.T) {
	if got := MergeSort([]int{-2, 5, 0, -7, 3}); !eq(got, []int{-7, -2, 0, 3, 5}) {
		t.Fatalf("got %v", got)
	}
}
